    assert slugify("Café au lait") == "caf-au-lait", "slugify('Café au lait')"

def test_only_separators_returns_empty():
    assert slugify("!!!") == "", "slugify('!!!')"

def test_empty_string_returns_empty():
    assert slugify("") == "", "slugify('')"

def test_already_slug_unchanged():
    assert slugify("hello-world") == "hello-world", "slugify('hello-world')"

def test_mixed_case_and_digits():
    assert slugify("ABC123") == "abc123", "slugify('ABC123')"

def test_leading_trailing_separators_removed():
    assert slugify("---Hello---") == "hello", "slugify('---Hello---')"

def test_unicode_separator_runs_collapse():
    assert slugify("a!!!b") == "a-b", "slugify('a!!!b')"
